/**
 * @param {number[]} nums
 * @param {number} k
 * @param {number} m
 * @return {number}
 */
var maximumAND = function(nums, k, m) {
    let ans = 0;
    const n = nums.length;
    const costs = new Array(n);
    // Step 1: decide bits from the top
    for (let bit = 30; bit >= 0; bit--) {
        const candidate = ans | (1 << bit);
        let zeroCount = 0;
        // Step 2: cheapest y >= a whose bits include every bit of candidate
        for (let i = 0; i < n; i++) {
            const a = nums[i];
            if ((a & candidate) === candidate) {
                costs[i] = 0;
                zeroCount++;
            } else {
                const missing = candidate & ~a;
                const h = 31 - Math.clz32(missing);           // highest missing bit
                const y = ((a >>> h) << h) | (1 << h) | candidate;   // set it, clear below, copy candidate
                costs[i] = y - a;
            }
        }
        if (zeroCount >= m) {
            ans = candidate;
            continue;
        }
        // Step 3: keep the bit if the m cheapest elements fit in the budget
        costs.sort((a, b) => a - b);
        let sum = 0;
        let possible = true;
        for (let i = 0; i < m; i++) {
            sum += costs[i];
            if (sum > k) {
                possible = false;
                break;
            }
        }
        if (possible) {
            ans = candidate;
        }
    }
    return ans;
};

